use std::error::Error;
use std::fs;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

use voon_core::db::{CachedTags, Index};
use voon_core::scan::{DiskTags, FileStamp, IssueKind, NoTags, TagReader, scan_root};
use voon_core::tags::TagInfo;
use voon_core::{Album, AudioFormat};

type DiagnosticResult<T> = Result<T, Box<dyn Error>>;

struct RestorePermissions {
    path: PathBuf,
    original: fs::Permissions,
    restored: bool,
}

impl RestorePermissions {
    fn block(path: &Path) -> DiagnosticResult<Self> {
        let original = fs::metadata(path)?.permissions();
        fs::set_permissions(path, fs::Permissions::from_mode(0o000))?;
        Ok(Self {
            path: path.to_path_buf(),
            original,
            restored: false,
        })
    }

    fn restore(&mut self) -> DiagnosticResult<()> {
        fs::set_permissions(&self.path, self.original.clone())?;
        self.restored = true;
        Ok(())
    }
}

impl Drop for RestorePermissions {
    fn drop(&mut self) {
        if !self.restored {
            if let Err(error) = fs::set_permissions(&self.path, self.original.clone()) {
                eprintln!("PERMISSION RESTORE FAILED: {}: {error}", self.path.display());
            }
        }
    }
}

fn write_audio(root: &Path, relative: &str) -> DiagnosticResult<PathBuf> {
    let path = root.join(relative);
    fs::create_dir_all(path.parent().ok_or("audio path has no parent")?)?;
    fs::write(&path, b"synthetic audio placeholder")?;
    Ok(path)
}

fn display_album(album: &Album) {
    println!("album_path={}", album.path.display());
    println!("album_metadata={:?}", album.metadata.entries());
    for (position, track) in album.tracks().enumerate() {
        println!(
            "track[{position}]: title={:?}, artist={:?}, duration_ms={:?}, source={:?}",
            track.title, track.artist, track.properties.duration_ms, track.source
        );
    }
}

fn experiment_partial_directory_failure(run: &Path) -> DiagnosticResult<()> {
    println!("EXPERIMENT 1: unreadable child directory and completed-scan storage");
    let root = run.join("unreadable-child/Music");
    write_audio(&root, "A/01.flac")?;
    write_audio(&root, "B/01.flac")?;
    let mut index = Index::open_in_memory()?;
    let first = scan_root(&root, &mut NoTags);
    let first_store = index.store_scan(&root, &first);
    println!("initial_store_result={first_store:?}");
    first_store?;
    println!("initial_album_count={}", index.albums()?.len());
    println!("initial_issues={:?}", first.issues);

    let album_a = root.join("A");
    let mut permissions = RestorePermissions::block(&album_a)?;
    let probe = fs::read_dir(&album_a);
    match probe {
        Ok(_) => {
            println!("permission_probe=READABLE; experiment cannot establish precondition");
            permissions.restore()?;
            return Err("chmod 000 did not prevent directory listing".into());
        }
        Err(error) => println!("permission_probe_error={error:?}"),
    }

    let device_before = root.metadata().ok().map(|metadata| metadata.dev());
    let scan = scan_root(&root, &mut NoTags);
    let device_after = root.metadata().ok().map(|metadata| metadata.dev());
    // The current DiskScanner checks only root-level Unreadable issues.
    // This mirrors its branch decision; no GPUI window is exercised here.
    let unavailable = !root.is_dir()
        || device_before != device_after
        || scan.issues.iter().any(|issue| {
            issue.path == root && matches!(issue.kind, IssueKind::Unreadable { .. })
        });
    println!("root_is_directory={}", root.is_dir());
    println!("device_before={device_before:?}; device_after={device_after:?}");
    println!("rescan_album_count={}; cancelled={}", scan.albums.len(), scan.cancelled);
    println!("rescan_issues={:?}", scan.issues);
    println!("mirrored_app_unavailable={unavailable}");
    let store_result = if unavailable || scan.cancelled {
        println!("mirrored_app_storage_branch=store_partial_scan");
        index.store_partial_scan(&root, &scan)
    } else {
        println!("mirrored_app_storage_branch=store_scan (B keeps result nonempty)");
        index.store_scan(&root, &scan)
    };
    println!("rescan_store_result={store_result:?}");
    store_result?;
    let after = index.albums()?;
    println!("indexed_album_count_after={}", after.len());
    println!("indexed_album_paths_after={:?}", after.iter().map(|album| &album.path).collect::<Vec<_>>());
    println!("album_A_still_indexed={}", index.album(&album_a)?.is_some());

    permissions.restore()?;
    println!("restored_A_permissions={:o}", fs::metadata(&album_a)?.permissions().mode() & 0o777);
    println!("restored_A_directory_readable={}", fs::read_dir(&album_a).is_ok());
    println!("scope=core scan + mirrored current application completion branch; no GUI automation");
    Ok(())
}

struct InjectedTags {
    calls: Arc<AtomicUsize>,
    result: Option<TagInfo>,
}

impl TagReader for InjectedTags {
    fn read(&mut self, _: &Path, _: AudioFormat, _: FileStamp) -> Option<TagInfo> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        self.result.clone()
    }
}

fn successful_tags(calls: Arc<AtomicUsize>) -> InjectedTags {
    InjectedTags {
        calls,
        result: Some(TagInfo {
            title: Some("Recovered Track".into()),
            album: Some("Recovered Album".into()),
            album_artist: Some("Recovered Album Artist".into()),
            ..TagInfo::default()
        }),
    }
}

fn experiment_negative_tag_cache(run: &Path) -> DiagnosticResult<()> {
    println!("EXPERIMENT 2: same-stamp negative tag cache with injected recovery");
    let root = run.join("negative-cache/Music");
    let audio = write_audio(&root, "Album/01.flac")?;
    let mut index = Index::open_in_memory()?;
    let before_stamp = FileStamp::of(&audio).ok_or("missing initial file stamp")?;
    let first_calls = Arc::new(AtomicUsize::new(0));
    let first_scan = {
        let first_reader = InjectedTags { calls: first_calls.clone(), result: None };
        let mut cached = CachedTags::new(&index, first_reader);
        let scan = scan_root(&root, &mut cached);
        println!("first_cached_disk_reads={}; first_underlying_calls={}", cached.reads, first_calls.load(Ordering::SeqCst));
        scan
    };
    index.store_scan(&root, &first_scan)?;
    println!("first_scan_cancelled={}; first_scan_issues={:?}", first_scan.cancelled, first_scan.issues);
    display_album(&first_scan.albums[0]);

    let second_calls = Arc::new(AtomicUsize::new(0));
    let second_scan = {
        let mut cached = CachedTags::new(&index, successful_tags(second_calls.clone()));
        let scan = scan_root(&root, &mut cached);
        println!("second_cached_disk_reads={}; second_underlying_calls={}", cached.reads, second_calls.load(Ordering::SeqCst));
        scan
    };
    index.store_scan(&root, &second_scan)?;
    let after_stamp = FileStamp::of(&audio).ok_or("missing subsequent file stamp")?;
    println!("before_stamp={before_stamp:?}; after_stamp={after_stamp:?}; unchanged={}", before_stamp == after_stamp);
    println!("second_scan_cancelled={}; second_scan_issues={:?}", second_scan.cancelled, second_scan.issues);
    display_album(&second_scan.albums[0]);
    println!("indexed_after_second_metadata={:?}", index.albums()?[0].metadata.entries());

    let control_calls = Arc::new(AtomicUsize::new(0));
    let control_scan = scan_root(&root, &mut successful_tags(control_calls.clone()));
    println!("uncached_control_underlying_calls={}", control_calls.load(Ordering::SeqCst));
    display_album(&control_scan.albums[0]);
    println!("scope=TagReader seam fault injection; no real SMB fault was induced");
    Ok(())
}

fn experiment_dff_cue(run: &Path) -> DiagnosticResult<()> {
    println!("EXPERIMENT 3: DFF + two-track CUE timing and artist");
    let root = run.join("dff-cue/Music");
    let audio = write_audio(&root, "DFF Album/image.dff")?;
    let album_path = audio.parent().ok_or("DFF album has no parent")?;
    fs::write(album_path.join("album.cue"), r#"PERFORMER "Album Performer"
TITLE "DFF CUE Diagnostic"
FILE "image.dff" WAVE
  TRACK 01 AUDIO
    TITLE "First Track"
    PERFORMER "First Artist"
    INDEX 01 00:00:00
  TRACK 02 AUDIO
    TITLE "Second Track"
    PERFORMER "Second Artist"
    INDEX 01 03:00:00
"#)?;
    for (label, tags) in [("NoTags", &mut NoTags as &mut dyn TagReader), ("DiskTags", &mut DiskTags as &mut dyn TagReader)] {
        let scan = scan_root(&root, tags);
        println!("reader={label}; album_count={}; cancelled={}; issues={:?}", scan.albums.len(), scan.cancelled, scan.issues);
        display_album(&scan.albums[0]);
        let mut index = Index::open_in_memory()?;
        index.store_scan(&root, &scan)?;
        println!("reader={label}; indexed round trip:");
        display_album(&index.album(album_path)?.ok_or("DFF album missing from index")?);
    }
    println!("expected_first_duration_from_CUE_only_ms=180000");
    println!("scope=core scanner and local in-memory index; UI artist rendering not exercised");
    Ok(())
}

fn main() -> DiagnosticResult<()> {
    let run_id = SystemTime::now().duration_since(UNIX_EPOCH)?.as_nanos();
    let run = PathBuf::from("/private/tmp/voon-roon-analysis/repro/fixtures").join(run_id.to_string());
    fs::create_dir_all(&run)?;
    println!("diagnostic_fixture_root={}", run.display());
    println!("All databases are in memory; only synthetic fixture files are used.");
    experiment_partial_directory_failure(&run)?;
    experiment_negative_tag_cache(&run)?;
    experiment_dff_cue(&run)?;
    println!("DIAGNOSTICS COMPLETED");
    Ok(())
}
